//! Relay action projections.

use crate::channel::{ChannelOutboundIntent, OutboundPayload};
use serde_json::{Map, Value, json};

/// Project a provider-neutral outbound intent to the Hermes relay `send` action.
pub fn relay_send_action_from_outbound_intent(intent: &ChannelOutboundIntent) -> Value {
    let mut metadata = Map::new();
    metadata.insert(
        "idempotency_key".to_string(),
        Value::String(intent.idempotency_key.clone()),
    );
    metadata.insert(
        "channel_id".to_string(),
        Value::String(intent.channel_id.clone()),
    );
    metadata.insert(
        "conversation_id".to_string(),
        Value::String(intent.conversation_id.clone()),
    );
    metadata.insert("durability".to_string(), json!(intent.durability));
    if let Some(thread_id) = intent.thread_id.as_deref() {
        metadata.insert(
            "thread_id".to_string(),
            Value::String(thread_id.to_string()),
        );
    }
    if !matches!(intent.payload, OutboundPayload::Text { .. }) {
        metadata.insert("payload".to_string(), json!(intent.payload));
    }

    json!({
        "op": "send",
        "chat_id": intent.conversation_id,
        "content": relay_send_content(&intent.payload),
        "reply_to": intent.reply_to_id,
        "metadata": metadata,
    })
}

fn relay_send_content(payload: &OutboundPayload) -> String {
    match payload {
        OutboundPayload::Text { text } => text.clone(),
        OutboundPayload::Media { text, .. } => text.clone().unwrap_or_default(),
        OutboundPayload::Voice { media_url } => media_url.clone(),
        OutboundPayload::Files { file_urls } => file_urls.join("\n"),
        OutboundPayload::Poll { question, .. } => question.clone(),
        OutboundPayload::PresentationBlocks { .. } => String::new(),
        OutboundPayload::NativeChannelData { data } => data
            .get("content")
            .or_else(|| data.get("text"))
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_string(),
    }
}

//! Portable first-run bind-code pairing / allowlist auth guard.
//!
//! First-connect authentication for channels (e.g. Telegram) that support
//! operator pairing. A one-time pairing code can be shown to the operator;
//! successful pairing issues a bearer token. Tokens can be persisted in config
//! so restarts don't require re-pairing. Bearer tokens are stored as SHA-256
//! hashes so plaintext never lands in config files.

use parking_lot::Mutex;
use sha2::{Digest, Sha256};
use std::collections::HashSet;
use std::sync::Arc;
use std::time::Instant;

/// Maximum failed pairing attempts before lockout.
pub const MAX_PAIR_ATTEMPTS: u32 = 5;
/// Lockout duration after too many failed pairing attempts.
pub const PAIR_LOCKOUT_SECS: u64 = 300; // 5 minutes

/// Manages pairing state for channels that use bearer-token auth after pairing.
///
/// Bearer tokens are stored as SHA-256 hashes to prevent plaintext exposure
/// in config files. When a new token is generated, the plaintext is returned
/// to the client once, and only the hash is retained.
// TODO: I've just made this work with parking_lot but it should use either flume or tokio's async mutexes
#[derive(Debug, Clone)]
pub struct PairingGuard {
    /// Whether pairing is required at all.
    require_pairing: bool,
    /// One-time pairing code (generated on startup, consumed on first pair).
    pairing_code: Arc<Mutex<Option<String>>>,
    /// Set of SHA-256 hashed bearer tokens (persisted across restarts).
    paired_tokens: Arc<Mutex<HashSet<String>>>,
    /// Brute-force protection: failed attempt counter + lockout time.
    failed_attempts: Arc<Mutex<(u32, Option<Instant>)>>,
}

impl PairingGuard {
    /// Create a new pairing guard.
    ///
    /// If `require_pairing` is true and no tokens exist yet, a fresh
    /// pairing code is generated and returned via `pairing_code()`.
    ///
    /// Existing tokens are accepted in both forms:
    /// - Plaintext (`zc_...`): hashed on load for backward compatibility
    /// - Already hashed (64-char hex): stored as-is
    pub fn new(require_pairing: bool, existing_tokens: &[String]) -> (Self, Option<String>) {
        let tokens: HashSet<String> = existing_tokens
            .iter()
            .map(|t| {
                if is_token_hash(t) {
                    t.clone()
                } else {
                    hash_token(t)
                }
            })
            .collect();
        let code = if require_pairing && tokens.is_empty() {
            Some(generate_code())
        } else {
            None
        };
        tracing::info!(
            "[openhuman:pairing] Guard created: require_pairing={}, existing_tokens={}, code_generated={}",
            require_pairing,
            tokens.len(),
            code.is_some()
        );
        let guard = Self {
            require_pairing,
            pairing_code: Arc::new(Mutex::new(code.clone())),
            paired_tokens: Arc::new(Mutex::new(tokens)),
            failed_attempts: Arc::new(Mutex::new((0, None))),
        };
        (guard, code)
    }

    /// The one-time pairing code (only set when no tokens exist yet).
    pub fn pairing_code(&self) -> Option<String> {
        self.pairing_code.lock().clone()
    }

    /// Invalidate the one-time pairing code without pairing a token.
    ///
    /// `try_pair` consumes the code as part of a successful `/bind <code>`, but
    /// some onboarding flows bind the operator through a different signal (e.g.
    /// the Telegram self-token `/start` path allowlists the first sender
    /// directly). Those paths must still finish the one-time flow so the code
    /// can't later be replayed by another sender who obtains it — call this once
    /// the operator is bound. Idempotent; a no-op if the code is already gone.
    pub fn invalidate_code(&self) {
        let mut code = self.pairing_code.lock();
        if code.is_some() {
            *code = None;
            tracing::info!(
                "[openhuman:pairing] one-time pairing code invalidated (operator onboarded)"
            );
        }
    }

    /// Whether pairing is required at all.
    pub fn require_pairing(&self) -> bool {
        self.require_pairing
    }

    fn try_pair_blocking(&self, code: &str) -> Result<Option<String>, u64> {
        // Check brute force lockout
        {
            let attempts = self.failed_attempts.lock();
            if let (count, Some(locked_at)) = &*attempts
                && *count >= MAX_PAIR_ATTEMPTS
            {
                let elapsed = locked_at.elapsed().as_secs();
                if elapsed < PAIR_LOCKOUT_SECS {
                    tracing::warn!(
                        "[openhuman:pairing] Pairing locked out: {} failed attempts, {}s remaining",
                        count,
                        PAIR_LOCKOUT_SECS - elapsed
                    );
                    return Err(PAIR_LOCKOUT_SECS - elapsed);
                }
            }
        }

        {
            let mut pairing_code = self.pairing_code.lock();
            if let Some(ref expected) = *pairing_code
                && constant_time_eq(code.trim(), expected.trim())
            {
                // Reset failed attempts on success
                {
                    let mut attempts = self.failed_attempts.lock();
                    *attempts = (0, None);
                }
                let token = generate_token();
                let mut tokens = self.paired_tokens.lock();
                tokens.insert(hash_token(&token));

                // Consume the pairing code so it cannot be reused
                *pairing_code = None;

                tracing::info!("[openhuman:pairing] Pairing successful, token issued");
                return Ok(Some(token));
            }
        }

        // Increment failed attempts
        {
            let mut attempts = self.failed_attempts.lock();
            attempts.0 += 1;
            tracing::warn!(
                "[openhuman:pairing] Pairing attempt failed ({}/{})",
                attempts.0,
                MAX_PAIR_ATTEMPTS
            );
            if attempts.0 >= MAX_PAIR_ATTEMPTS {
                attempts.1 = Some(Instant::now());
                tracing::warn!("[openhuman:pairing] Max attempts reached, lockout activated");
            }
        }

        Ok(None)
    }

    /// Attempt to pair with the given code. Returns a bearer token on success.
    /// Returns `Err(lockout_seconds)` if locked out due to brute force.
    pub async fn try_pair(&self, code: &str) -> Result<Option<String>, u64> {
        let this = self.clone();
        let code = code.to_string();
        // TODO: make this function the main one without spawning a task
        let handle = tokio::task::spawn_blocking(move || this.try_pair_blocking(&code));

        handle
            .await
            .expect("failed to spawn blocking task this should not happen")
    }

    /// Check if a bearer token is valid (compares against stored hashes).
    ///
    /// Always fails closed on empty/whitespace tokens. When pairing is not required,
    /// configured tokens are still honored if present; with no tokens configured,
    /// every request is rejected.
    pub fn is_authenticated(&self, token: &str) -> bool {
        if token.trim().is_empty() {
            tracing::debug!("[openhuman:pairing] is_authenticated: rejected empty bearer token");
            return false;
        }

        let tokens = self.paired_tokens.lock();
        if tokens.is_empty() {
            tracing::debug!(
                "[openhuman:pairing] is_authenticated: no paired tokens configured (require_pairing={})",
                self.require_pairing
            );
            return false;
        }

        let hashed = hash_token(token);
        let ok = tokens.contains(&hashed);
        if !ok {
            tracing::debug!("[openhuman:pairing] is_authenticated: bearer token not in paired set");
        }
        ok
    }

    /// Returns true if pairing is satisfied (has at least one token).
    pub fn is_paired(&self) -> bool {
        let tokens = self.paired_tokens.lock();
        !tokens.is_empty()
    }

    /// Get all paired token hashes (for persisting to config).
    pub fn tokens(&self) -> Vec<String> {
        let tokens = self.paired_tokens.lock();
        tokens.iter().cloned().collect()
    }
}

/// Generate a 6-digit numeric pairing code using cryptographically secure randomness.
pub fn generate_code() -> String {
    // UUID v4 uses getrandom (backed by /dev/urandom on Linux, BCryptGenRandom
    // on Windows) — a CSPRNG. We extract 4 bytes from it for a uniform random
    // number in [0, 1_000_000).
    //
    // Rejection sampling eliminates modulo bias: values above the largest
    // multiple of 1_000_000 that fits in u32 are discarded and re-drawn.
    // The rejection probability is ~0.02%, so this loop almost always exits
    // on the first iteration.
    const UPPER_BOUND: u32 = 1_000_000;
    const REJECT_THRESHOLD: u32 = (u32::MAX / UPPER_BOUND) * UPPER_BOUND;

    loop {
        let uuid = uuid::Uuid::new_v4();
        let bytes = uuid.as_bytes();
        let raw = u32::from_le_bytes([bytes[0], bytes[1], bytes[2], bytes[3]]);

        if raw < REJECT_THRESHOLD {
            return format!("{:06}", raw % UPPER_BOUND);
        }
    }
}

/// Generate a cryptographically-adequate bearer token with 256-bit entropy.
///
/// Uses `rand::rng()` which is backed by the OS CSPRNG
/// (/dev/urandom on Linux, BCryptGenRandom on Windows, SecRandomCopyBytes
/// on macOS). The 32 random bytes (256 bits) are hex-encoded for a
/// 64-character token, providing 256 bits of entropy.
pub fn generate_token() -> String {
    use rand::RngExt as _;
    let mut bytes = [0u8; 32];
    rand::rng().fill(&mut bytes);
    format!("zc_{}", hex::encode(bytes))
}

/// SHA-256 hash a bearer token for storage. Returns lowercase hex.
pub fn hash_token(token: &str) -> String {
    format!("{:x}", Sha256::digest(token.as_bytes()))
}

/// Check if a stored value looks like a SHA-256 hash (64 hex chars)
/// rather than a plaintext token.
pub fn is_token_hash(value: &str) -> bool {
    value.len() == 64 && value.chars().all(|c| c.is_ascii_hexdigit())
}

/// Constant-time string comparison to prevent timing attacks.
///
/// Does not short-circuit on length mismatch — always iterates over the
/// longer input to avoid leaking length information via timing.
pub fn constant_time_eq(a: &str, b: &str) -> bool {
    let a = a.as_bytes();
    let b = b.as_bytes();

    // Track length mismatch as a usize (non-zero = different lengths)
    let len_diff = a.len() ^ b.len();

    // XOR each byte, padding the shorter input with zeros.
    // Iterates over max(a.len(), b.len()) to avoid timing differences.
    let max_len = a.len().max(b.len());
    let mut byte_diff = 0u8;
    for i in 0..max_len {
        let x = *a.get(i).unwrap_or(&0);
        let y = *b.get(i).unwrap_or(&0);
        byte_diff |= x ^ y;
    }
    (len_diff == 0) & (byte_diff == 0)
}

//! Relay HMAC authentication primitives.

use base64::Engine;
use base64::engine::general_purpose::URL_SAFE_NO_PAD;
use hmac::{Hmac, Mac};
use sha2::Sha256;
use std::time::{SystemTime, UNIX_EPOCH};

pub const DELIVERY_TS_HEADER: &str = "x-relay-timestamp";
pub const DELIVERY_SIG_HEADER: &str = "x-relay-signature";
pub const DEFAULT_MAX_SKEW_SECONDS: i64 = 300;
pub const DEFAULT_UPGRADE_TTL_SECONDS: i64 = 300;

type HmacSha256 = Hmac<Sha256>;

/// HMAC-SHA256 hex digest of `payload` under `secret` using UTF-8 bytes.
pub fn sign(payload: &str, secret: &str) -> String {
    let mut mac =
        HmacSha256::new_from_slice(secret.as_bytes()).expect("HMAC accepts any key length");
    mac.update(payload.as_bytes());
    encode_hex(&mac.finalize().into_bytes())
}

/// Constant-time check against any secret in a rotation verify list.
pub fn verify_signature(payload: &str, sig_hex: &str, secrets: &[impl AsRef<str>]) -> bool {
    let Some(sig_bytes) = decode_hex(sig_hex) else {
        return false;
    };
    if sig_bytes.is_empty() {
        return false;
    }
    for secret in secrets {
        let mut mac = HmacSha256::new_from_slice(secret.as_ref().as_bytes())
            .expect("HMAC accepts any key length");
        mac.update(payload.as_bytes());
        if mac.verify_slice(&sig_bytes).is_ok() {
            return true;
        }
    }
    false
}

/// Build `base64url("{payload}:{exp}:{sig}")`.
pub fn make_token_at(
    payload: &str,
    secret: &str,
    ttl_seconds: i64,
    now_unix_seconds: i64,
) -> String {
    let exp = if ttl_seconds > 0 {
        now_unix_seconds.saturating_add(ttl_seconds)
    } else {
        0
    };
    let signed = format!("{payload}:{exp}");
    let sig = sign(&signed, secret);
    URL_SAFE_NO_PAD.encode(format!("{signed}:{sig}").as_bytes())
}

/// Build a token using the current system clock.
pub fn make_token(payload: &str, secret: &str, ttl_seconds: i64) -> String {
    make_token_at(payload, secret, ttl_seconds, now_unix_seconds())
}

pub fn make_upgrade_token_at(
    gateway_id: &str,
    secret: &str,
    ttl_seconds: i64,
    now_unix_seconds: i64,
) -> String {
    make_token_at(gateway_id, secret, ttl_seconds, now_unix_seconds)
}

pub fn make_upgrade_token(gateway_id: &str, secret: &str, ttl_seconds: i64) -> String {
    make_token(gateway_id, secret, ttl_seconds)
}

/// Verify a token and return the signed payload.
pub fn verify_token_at(
    token: &str,
    secrets: &[impl AsRef<str>],
    now_unix_seconds: i64,
) -> Option<String> {
    let decoded = URL_SAFE_NO_PAD.decode(token.as_bytes()).ok()?;
    let decoded = String::from_utf8(decoded).ok()?;
    let (payload_and_exp, sig) = decoded.rsplit_once(':')?;
    let (payload, exp) = payload_and_exp.rsplit_once(':')?;
    let exp = exp.parse::<i64>().ok()?;
    if exp != 0 && now_unix_seconds > exp {
        return None;
    }
    if verify_signature(&format!("{payload}:{exp}"), sig, secrets) {
        Some(payload.to_string())
    } else {
        None
    }
}

/// Verify a token using the current system clock.
pub fn verify_token(token: &str, secrets: &[impl AsRef<str>]) -> Option<String> {
    verify_token_at(token, secrets, now_unix_seconds())
}

/// Verify connector-to-gateway inbound delivery signature.
pub fn verify_delivery_signature_at(
    body_json: &str,
    timestamp: Option<&str>,
    signature: Option<&str>,
    verify_keys: &[impl AsRef<str>],
    max_skew_seconds: i64,
    now_unix_seconds: i64,
) -> bool {
    let (Some(timestamp), Some(signature)) = (timestamp, signature) else {
        return false;
    };
    let Ok(ts) = timestamp.parse::<i64>() else {
        return false;
    };
    if now_unix_seconds.abs_diff(ts) > max_skew_seconds as u64 {
        return false;
    }
    verify_signature(&delivery_payload(ts, body_json), signature, verify_keys)
}

pub fn verify_delivery_signature(
    body_json: &str,
    timestamp: Option<&str>,
    signature: Option<&str>,
    verify_keys: &[impl AsRef<str>],
) -> bool {
    verify_delivery_signature_at(
        body_json,
        timestamp,
        signature,
        verify_keys,
        DEFAULT_MAX_SKEW_SECONDS,
        now_unix_seconds(),
    )
}

pub fn delivery_payload(timestamp: i64, body_json: &str) -> String {
    format!("{timestamp}.{body_json}")
}

fn now_unix_seconds() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_secs() as i64)
        .unwrap_or(0)
}

fn encode_hex(bytes: &[u8]) -> String {
    const HEX: &[u8; 16] = b"0123456789abcdef";
    let mut out = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        out.push(HEX[(byte >> 4) as usize] as char);
        out.push(HEX[(byte & 0x0f) as usize] as char);
    }
    out
}

fn decode_hex(input: &str) -> Option<Vec<u8>> {
    if !input.len().is_multiple_of(2) {
        return None;
    }
    let mut out = Vec::with_capacity(input.len() / 2);
    let mut chars = input.as_bytes().iter().copied();
    while let (Some(high), Some(low)) = (chars.next(), chars.next()) {
        out.push((hex_value(high)? << 4) | hex_value(low)?);
    }
    Some(out)
}

fn hex_value(byte: u8) -> Option<u8> {
    match byte {
        b'0'..=b'9' => Some(byte - b'0'),
        b'a'..=b'f' => Some(byte - b'a' + 10),
        b'A'..=b'F' => Some(byte - b'A' + 10),
        _ => None,
    }
}

//! Credential helper utilities shared by channel controller implementations.

use serde_json::Value;

use super::ChannelAuthMode;

/// Credential provider key for channel connections: `"channel:{id}:{mode}"`.
pub fn channel_credential_provider(channel_id: &str, mode: ChannelAuthMode) -> String {
    format!("channel:{channel_id}:{mode}")
}

/// Parse an optional allowlist JSON field into canonical identities.
///
/// Accepts comma/newline separated strings or arrays of strings. Leading `@`
/// prefixes are stripped, whitespace is trimmed, and entries are lowercased and
/// deduplicated case-insensitively. Non-string values are ignored.
pub fn parse_allowed_users(value: Option<&Value>) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();

    let mut push_identity = |raw: &str| {
        let trimmed = raw.trim();
        if trimmed.is_empty() {
            return;
        }
        let normalized = trimmed.trim_start_matches('@').trim();
        if normalized.is_empty() {
            return;
        }
        let canonical = normalized.to_lowercase();
        if !out
            .iter()
            .any(|existing| existing.eq_ignore_ascii_case(&canonical))
        {
            out.push(canonical);
        }
    };

    match value {
        Some(Value::String(s)) => {
            for part in s.split([',', '\n', '\r']) {
                push_identity(part);
            }
        }
        Some(Value::Array(items)) => {
            for item in items {
                if let Some(s) = item.as_str() {
                    for part in s.split([',', '\n', '\r']) {
                        push_identity(part);
                    }
                }
            }
        }
        _ => {}
    }

    out
}

