use crate::adapters::{LocalChannelAdapter, LocalOutboundSink};
use crate::channel::{
    ChannelAdapter, ChannelDescriptor, ChannelInboundEnvelope, ChannelInboundSink,
    ChannelOutboundIntent, ChannelSendError, ChannelStaticCapabilities, DeliveryDurability,
    MessageReceipt, OutboundPayload,
};
use async_trait::async_trait;
use std::sync::{Arc, Mutex};

#[derive(Default)]
struct RecordingOutboundSink {
    ids: Mutex<Vec<String>>,
}

#[async_trait]
impl LocalOutboundSink for RecordingOutboundSink {
    async fn send(
        &self,
        intent: ChannelOutboundIntent,
    ) -> Result<MessageReceipt, ChannelSendError> {
        self.ids
            .lock()
            .expect("ids lock")
            .push(intent.idempotency_key);
        Ok(MessageReceipt {
            primary_platform_message_id: Some("local-1".into()),
            platform_message_ids: vec!["local-1".into()],
            sent_at: 1,
            ..Default::default()
        })
    }
}

struct NoopInboundSink;

#[async_trait]
impl ChannelInboundSink for NoopInboundSink {
    async fn push(&self, _envelope: ChannelInboundEnvelope) -> Result<(), ChannelSendError> {
        Ok(())
    }
}

fn local_adapter(sink: Arc<RecordingOutboundSink>) -> LocalChannelAdapter {
    LocalChannelAdapter::new(
        ChannelDescriptor {
            id: "local".into(),
            display_name: "Local".into(),
            account_id: Some("host".into()),
            ..Default::default()
        },
        ChannelStaticCapabilities {
            reply: true,
            ..Default::default()
        },
        sink,
    )
}

#[tokio::test]
async fn local_adapter_delegates_outbound_delivery() {
    let sink = Arc::new(RecordingOutboundSink::default());
    let adapter = local_adapter(sink.clone());

    let receipt = adapter
        .send(ChannelOutboundIntent {
            idempotency_key: "turn-1:text".into(),
            channel_id: "local".into(),
            conversation_id: "chat-1".into(),
            reply_to_id: None,
            thread_id: None,
            durability: DeliveryDurability::BestEffort,
            payload: OutboundPayload::Text { text: "hi".into() },
        })
        .await
        .expect("send");

    assert_eq!(
        receipt.primary_platform_message_id.as_deref(),
        Some("local-1")
    );
    assert_eq!(
        sink.ids.lock().expect("ids lock").as_slice(),
        ["turn-1:text"]
    );
}

#[tokio::test]
async fn local_adapter_reports_configured_status() {
    let adapter = local_adapter(Arc::new(RecordingOutboundSink::default()));
    adapter.start(&NoopInboundSink).await.expect("start");

    let status = adapter.status().await.expect("status");
    assert_eq!(status.channel_id, "local");
    assert_eq!(status.account_id.as_deref(), Some("host"));
    assert!(
        status
            .states
            .iter()
            .any(|state| { *state == crate::controllers::ChannelAccountState::Configured })
    );
    assert!(adapter.static_capabilities().reply);
}

use super::*;

fn strip_indicators(chunks: &[String]) -> Vec<String> {
    chunks
        .iter()
        .map(|chunk| {
            chunk
                .rsplit_once(" (")
                .map(|(body, _)| body.to_string())
                .unwrap_or_else(|| chunk.clone())
        })
        .collect()
}

fn fences_balanced(chunk: &str) -> bool {
    chunk.matches("```").count().is_multiple_of(2)
}

#[test]
fn measures_utf16_units_for_astral_characters() {
    assert_eq!(measure_text("hello", LengthUnit::Utf16Units), 5);
    assert_eq!(measure_text("你好", LengthUnit::Utf16Units), 2);
    assert_eq!(measure_text("😀", LengthUnit::Utf16Units), 2);
    assert_eq!(measure_text("hi😀", LengthUnit::Utf16Units), 4);
    assert_eq!(measure_text("𝄞", LengthUnit::Utf16Units), 2);
}

#[test]
fn prefix_within_utf16_limit_does_not_split_surrogate_pairs() {
    assert_eq!(
        prefix_within_limit("hello world", 5, LengthUnit::Utf16Units),
        "hello"
    );
    assert_eq!(prefix_within_limit("a😀b", 2, LengthUnit::Utf16Units), "a");
    assert_eq!(prefix_within_limit("😀x", 2, LengthUnit::Utf16Units), "😀");
    assert_eq!(
        prefix_within_limit(&"😀".repeat(10), 6, LengthUnit::Utf16Units),
        "😀😀😀"
    );
}

#[test]
fn utf16_chunking_splits_emoji_case_that_character_count_would_pass() {
    let text = "😀".repeat(2049);
    assert_eq!(measure_text(&text, LengthUnit::Characters), 2049);
    assert_eq!(measure_text(&text, LengthUnit::Utf16Units), 4098);

    let char_chunks = chunk_text_with_options(
        &text,
        TextChunkOptions {
            limit: 4096,
            length_unit: LengthUnit::Characters,
            indicators: false,
            ..Default::default()
        },
    );
    assert_eq!(char_chunks.len(), 1);

    let utf16_chunks = chunk_text_with_options(
        &text,
        TextChunkOptions {
            limit: 4096,
            length_unit: LengthUnit::Utf16Units,
            indicators: true,
            ..Default::default()
        },
    );
    assert!(utf16_chunks.len() > 1);
    for chunk in &utf16_chunks {
        assert!(measure_text(chunk, LengthUnit::Utf16Units) <= 4096);
    }
}

#[test]
fn length_chunking_prefers_newline_then_space_boundaries() {
    let chunks = chunk_text_with_options(
        "paragraph one line\n\nparagraph two starts here and continues",
        TextChunkOptions {
            limit: 40,
            indicators: false,
            ..Default::default()
        },
    );
    assert_eq!(
        chunks.join(""),
        "paragraph one line\n\nparagraph two starts here and continues"
    );
    assert_eq!(chunks[0].trim_end(), "paragraph one line");

    let chunks = chunk_text_with_options(
        "This is a message that should break nicely near a word boundary.",
        TextChunkOptions {
            limit: 30,
            indicators: false,
            ..Default::default()
        },
    );
    assert!(!chunks[0].ends_with("nic"));
    assert!(chunks.iter().all(|chunk| chunk.len() <= 30));
    assert_eq!(
        chunks.join(""),
        "This is a message that should break nicely near a word boundary."
    );
}

#[test]
fn length_chunking_preserves_boundary_whitespace() {
